  async function unlockEncryption(){if(busy)return;setBusy(true);setStatus('Unlocking encrypted cloud…');try{const remote=await fetchCloud();if(!isEncryptedPayload(remote?.payload))throw new Error('The current cloud copy is not encrypted.');const secret=$('cloudUnlockSecret').value;if(!secret)throw new Error(unlockMethod==='passphrase'?'Enter the encryption passphrase.':'Enter the recovery key.');const master=unlockMethod==='passphrase'?await masterFromPassphrase(secret,remote.payload):await masterFromRecovery(secret,remote.payload);cryptoProfile=profileFromEncrypted(remote.payload);masterKeyBytes=master;masterKeyId=cryptoProfile.keyId;await decryptCloudPayload(remote.payload,master);saveCryptoProfile(cryptoProfile);saveDeviceMasterKey(master,cryptoProfile.keyId,$('cloudUnlockRemember').checked);$('cloudUnlockSecret').value='';hideEncryptionPanel();setStatus('Encrypted cloud unlocked on this device. Safe Sync can now compare the copies.','success');await updateUi();scheduleAutoSync('encryption-unlocked',250)}catch(err){masterKeyBytes=null;masterKeyId=null;setStatus(err?.message||String(err),'error')}finally{setBusy(false);await updateUi()}}
