  async function changeEncryptionPassphrase(){if(busy)return;const p=$('cloudNewEncryptionPassphrase').value,c=$('cloudNewEncryptionPassphraseConfirm').value;if(p.length<12){setKeyStatus('Use a new encryption passphrase with at least 12 characters.','error');return}if(p!==c){setKeyStatus('The new encryption passphrases do not match.','error');return}if(!confirm('Change the encryption passphrase?\n\nRosterBot will create a new cloud revision and permanently remove older cloud revision history so the OLD passphrase wrapper cannot be recovered from history. Your current roster data and master encryption key stay the same.'))return;setBusy(true);setKeyStatus('Changing encryption passphrase…');try{const remote=await fetchCloud();if(!isEncryptedPayload(remote?.payload)||!hasMasterFor(remote.payload))throw new Error('Encrypted cloud must be unlocked first.');const a=await analyseSync(remote);if(a.kind!=='up-to-date')throw new Error('Make this device Up to date before changing the encryption passphrase.');const wrap=await makePassphraseWrap(p,remote.payload.crypto.keyId),envelope=envelopeWithWrappers(remote.payload,{passphraseWrap:wrap}),result=await rotateEncryptionWrappers(envelope,'passphrase-change');const testMaster=await masterFromPassphrase(p,result.payload);if(!bytesEqual(testMaster,masterKeyBytes))throw new Error('The new cloud wrapper was saved, but the new passphrase failed local verification. Keep the old credential and stop here.');$('cloudNewEncryptionPassphrase').value='';$('cloudNewEncryptionPassphraseConfirm').value='';hideEncryptionPanel();clearAutoHold();setKeyStatus(`Encryption passphrase changed and verified at cloud revision ${result.revision}. Removed ${result.deletedCount} older revision${result.deletedCount===1?'':'s'}; the old cloud passphrase wrapper is no longer retained.`,'success');await updateUi()}catch(err){setKeyStatus(keyManagementError(err),'error')}finally{setBusy(false);await updateUi()}}
