  async function commitRecoveryRotation(){if(busy||!pendingRecoveryRotation)return;if(!$('cloudRecoveryRotateSaved').checked){setKeyStatus('Confirm that you saved the NEW recovery key first.','error');return}if(!confirm('Replace the cloud recovery key?\n\nRosterBot will create a new cloud revision and permanently remove older cloud revision history so the OLD recovery wrapper cannot be recovered from history. Make sure the new recovery key is saved before continuing.'))return;setBusy(true);setKeyStatus('Replacing recovery key…');try{const remote=await fetchCloud();if(!isEncryptedPayload(remote?.payload)||!hasMasterFor(remote.payload))throw new Error('Encrypted cloud must be unlocked first.');if(Number(remote.revision)!==Number(pendingRecoveryRotation.baseRevision)||remote.payload.crypto.keyId!==pendingRecoveryRotation.keyId)throw new Error('The cloud changed after the new recovery key was generated. Nothing was changed. Generate a fresh recovery key and try again.');const a=await analyseSync(remote);if(a.kind!=='up-to-date')throw new Error('Make this device Up to date before replacing the recovery key.');const envelope=envelopeWithWrappers(remote.payload,{recoveryWrap:pendingRecoveryRotation.wrap}),result=await rotateEncryptionWrappers(envelope,'recovery-key-change');pendingRecoveryRotation=null;$('cloudRecoveryRotateKeyValue').textContent='—';$('cloudRecoveryRotateSaved').checked=false;$('cloudCommitRecoveryRotate').disabled=true;hideEncryptionPanel();clearAutoHold();setKeyStatus(`Recovery key replaced and verified at cloud revision ${result.revision}. Removed ${result.deletedCount} older revision${result.deletedCount===1?'':'s'}; the old recovery key is no longer retained by cloud revision history.`,'success');await updateUi()}catch(err){setKeyStatus(keyManagementError(err),'error')}finally{setBusy(false);await updateUi()}}
