  async function signIn(){if(busy)return;setBusy(true);setStatus('Signing in…');try{if(!config)throw new Error('Cloud service is not configured on this device. Open Connection settings first.');const email=$('cloudEmail').value.trim(),password=$('cloudPassword').value;if(!email||!password)throw new Error('Enter your email and password.');await authPassword(email,password);loadCryptoForSession(true);$('cloudPassword').value='';await fetchCloud();const signInAnalysis=await analyseSync(cloudRow);lastAnalysis=signInAnalysis;if(['up-to-date','unlinked-same'].includes(signInAnalysis.kind)){setStatus('Signed in. This device already matches the cloud.','success');await updateUi();scheduleAutoSync('sign-in',600)}else if(signInAnalysis.kind==='create'){setStatus('Signed in. This account has no cloud copy yet. Nothing was uploaded; use Sync now when you are ready.','success');await updateUi()}else{markAutoHold('sign-in-review');setStatus(signInAnalysis.kind==='locked'?'Signed in. Nothing was uploaded or downloaded. Unlock the encrypted cloud copy, review it, then choose Sync now.':'Signed in. Nothing was uploaded or downloaded. Review the device and cloud copies before choosing Sync now or which copy to use.','success');await updateUi()}}catch(err){const msg=String(err?.message||err);setStatus(/email.*not.*confirm/i.test(msg)?'That email address has not been confirmed yet. Check your inbox, confirm it, then try signing in again.':msg,'error')}finally{setBusy(false);await updateUi()}}
  async function createAccount(){if(busy)return;setBusy(true);setStatus('Creating account…');try{if(!config)throw new Error('Cloud service is not configured on this device. Open Connection settings first.');const email=$('cloudSignupEmail').value.trim(),password=$('cloudSignupPassword').value,confirm=$('cloudSignupConfirm').value;if(!email||!/^\S+@\S+\.\S+$/.test(email))throw new Error('Enter a valid email address.');if(password.length<10)throw new Error('Use a password with at least 10 characters.');if(password!==confirm)throw new Error('The two passwords do not match.');const data=await authSignup(email,password);$('cloudSignupPassword').value='';$('cloudSignupConfirm').value='';if(data?.access_token&&data?.user){await fetchCloud();setStatus('Account created and signed in. Nothing has been uploaded yet; use Sync now when you are ready.','success');await updateUi();return}$('cloudEmail').value=email;setAuthMode('signin');setStatus('Account request received. Check that email for a confirmation message. The confirmation link should return to this RosterBot page; after verification, sign in normally.','success')}catch(err){setStatus(err?.message||String(err),'error')}finally{setBusy(false);await updateUi()}}
  async function signOut(){if(busy)return;setBusy(true);const keptTrusted=isCurrentDeviceRemembered();try{if(session?.access_token){try{await api('/auth/v1/logout',{method:'POST',body:null,auth:true,prefer:''})}catch(_){}}storeSession(null);clearCryptoMemory();cloudRow=null;lastAnalysis=null;lastCloudError=null;$('cloudHistoryPanel').hidden=true;setStatus(keptTrusted?'Signed out. Local RosterBot data remains on this device, and this browser stays trusted for the encrypted cloud key. Sign in again to reuse it.':'Signed out. Local RosterBot data remains on this device.','success');await updateUi()}finally{setBusy(false)}}
  async function rpcSave(expected,{encrypt=null}={}){const plain=localPayload(),useEncryption=encrypt===true||(encrypt!==false&&encryptionExpected());let payload=plain,hash;if(useEncryption){if(!masterKeyBytes||!cryptoProfile?.keyId)throw new Error('Encrypted cloud is locked on this device.');hash=await hmacFingerprint(plain,masterKeyBytes);payload=await encryptCloudPayload(plain,masterKeyBytes,cryptoProfile,hash)}else hash=await storageHash(plain);const result=await api('/rest/v1/rpc/save_roster_state',{method:'POST',body:{expected_revision:Number(expected||0),new_schema_version:4,new_payload:payload,new_client_id:clientId()}});const row=Array.isArray(result)?result[0]:result;if(!row?.revision)throw new Error('Cloud save returned no revision.');setMeta({baseRevision:Number(row.revision),localHash:hash,lastSyncedAt:nowIso(),lastDirection:'upload',cloudUpdatedAt:row.updated_at||null,encryption:useEncryption?'v1':null});localStorage.removeItem('rosterbot-cleared-v1');await fetchCloud();return row}
  async function advancedUpload({forceReplace=false}={}){if(busy)return;setBusy(true);setStatus('Preparing cloud upload…');try{await ensureSession();const remote=await fetchCloud(),meta=getMeta();let expected=0;if(remote){if(forceReplace){if(!confirm(`Replace cloud revision ${remote.revision} with the RosterBot data on this device?\n\nThis creates a NEW revision; existing revision history remains available.`))return;expected=Number(remote.revision)}else if(meta?.baseRevision==null){throw new Error('This device has never synced from this existing cloud state. Use Safe Sync to review the copies, restore the cloud copy, or deliberately replace it.')}else expected=Number(meta.baseRevision)}else if(forceReplace){if(!confirm('Create a new cloud state from the data on this device?'))return;expected=0}const row=await rpcSave(expected);clearAutoHold();setStatus(`Uploaded successfully. Cloud revision ${row.revision}.`,'success');await updateUi()}catch(err){if(String(err.message).includes('revision_conflict')){setStatus(`Upload blocked: ${err.message}. Another device changed the cloud after this device last checked. Nothing was overwritten.`, 'error');try{await fetchCloud();await updateUi()}catch(_){}}else setStatus(err.message,'error')}finally{setBusy(false)}}
  function saveSafety(){const safety={createdAt:nowIso(),payload:localPayload()};localStorage.setItem(SAFETY_KEY,JSON.stringify(safety));return safety}
  async function applyPayload(payload,{baseRevision=null,direction='restore'}={}){if(!compatiblePayload(payload))throw new Error('That cloud revision is not a compatible RosterBot state.');const plain=isEncryptedPayload(payload)?await decryptCloudPayload(payload):payload;saveSafety();const keys=syncKeys(),storage=normalizedStorage(plain.storage||{}),priorSession=jparse(localStorage.getItem('rosterbot-session-settings-v1'),{})||{},volatile={};for(const k of SESSION_VOLATILE)if(Object.prototype.hasOwnProperty.call(priorSession,k))volatile[k]=priorSession[k];autoSuppress++;try{for(const key of keys)localStorage.removeItem(key);for(const key of keys){if(!Object.prototype.hasOwnProperty.call(storage,key))continue;if(key==='rosterbot-session-settings-v1'){const incoming=jparse(storage[key],{})||{};localStorage.setItem(key,JSON.stringify({...incoming,...volatile}))}else localStorage.setItem(key,String(storage[key]))}localStorage.setItem('rosterbot-db-schema-v1',String(plain.schemaVersion||4));localStorage.removeItem('rosterbot-cleared-v1')}finally{autoSuppress=Math.max(0,autoSuppress-1)}const expectedStorage={...normalizedStorage(plain.storage||{}),'rosterbot-db-schema-v1':String(plain.schemaVersion||4)},actualStorage=normalizedStorage(localPayload().storage);if(canonical(actualStorage)!==canonical(expectedStorage))throw new Error('Cloud restore verification failed: the local copy did not exactly match the selected cloud payload. The cloud copy was not changed.');const hash=isEncryptedPayload(payload)?await hmacFingerprint(plain,masterKeyBytes):await storageHash(plain);if(baseRevision!=null)setMeta({baseRevision:Number(baseRevision),localHash:hash,lastSyncedAt:nowIso(),lastDirection:direction,encryption:isEncryptedPayload(payload)?'v1':null});try{await window.RosterBotDiary?.mirrorNow?.()}catch(_){}}
  async function restoreCloud({confirmed=false}={}){if(busy)return;setBusy(true);try{const remote=await fetchCloud();if(isEncryptedPayload(remote?.payload)&&!hasMasterFor(remote.payload)){showEncryptionPanel('unlock');throw new Error('Encrypted cloud is locked on this device. Unlock it first.');}if(!remote)throw new Error('There is no cloud state to restore.');if(!compatiblePayload(remote.payload))throw new Error('The current cloud row is not a compatible RosterBot payload.');if(!confirmed&&!confirm(`Restore cloud revision ${remote.revision} to this device?\n\nYour current local RosterBot data will be replaced. RosterBot will keep one local safety snapshot so you can undo this restore.`))return;await applyPayload(remote.payload,{baseRevision:remote.revision,direction:'download'});clearAutoHold();setStatus(`Restored cloud revision ${remote.revision}. Reloading…`,'success');setTimeout(()=>location.reload(),450)}catch(err){setStatus(err.message,'error')}finally{setBusy(false)}}
  async function syncNow(){if(busy)return;setBusy(true);setStatus('Checking both copies…');try{await ensureSession();const remote=await fetchCloud(),a=await analyseSync(remote);lastAnalysis=a;await updateUi();if(a.kind==='locked'){showEncryptionPanel('unlock');setStatus('Encrypted cloud is locked on this device. Unlock it to continue.','error');return}switch(a.kind){
      case 'create':{const row=await rpcSave(0);clearAutoHold();setStatus(`Synced. Created cloud revision ${row.revision}.`,'success');await updateUi();break}
      case 'up-to-date':{setMeta({baseRevision:Number(remote.revision),localHash:a.localHash,lastSyncedAt:nowIso(),lastDirection:'verified',encryption:isEncryptedPayload(remote?.payload)?'v1':null});clearAutoHold();setStatus('Already up to date. No data transfer was needed.','success');await updateUi();break}
      case 'unlinked-same':{setMeta({baseRevision:Number(remote.revision),localHash:a.localHash,lastSyncedAt:nowIso(),lastDirection:'linked-identical',encryption:isEncryptedPayload(remote?.payload)?'v1':null});clearAutoHold();setStatus(`This device already matched cloud revision ${remote.revision}; it is now linked without replacing either copy.`,'success');await updateUi();break}
      case 'local-only':{const fromHistory=String(a?.meta?.lastDirection||'').match(/^history-(\d+)$/),row=await rpcSave(Number(remote.revision));clearAutoHold();setStatus(fromHistory?`Historical revision ${fromHistory[1]} is now the current cloud copy as revision ${row.revision}.`:`Synced this device to cloud revision ${row.revision}.`,'success');await updateUi();break}
      case 'cloud-only':{if(!confirm(`Cloud revision ${remote.revision} contains newer changes and this device has no unsynced local changes.\n\nUpdate this device from the cloud now? A local safety snapshot will be kept.`)){setStatus('Cloud update cancelled. Nothing changed.');break}await applyPayload(remote.payload,{baseRevision:remote.revision,direction:'safe-download'});clearAutoHold();setStatus(`Updated this device from cloud revision ${remote.revision}. Reloading…`,'success');setTimeout(()=>location.reload(),450);break}
      case 'conflict':setStatus('Sync stopped safely: both copies changed. Choose which copy to keep; nothing was overwritten.','error');break;
      case 'unlinked-different':setStatus('Sync stopped safely: this browser and cloud contain different data and have no shared sync baseline. Choose which copy to use.','error');break;
      case 'local-cleared':setStatus('Sync stopped safely: local data was cleared while a cloud copy still exists. Choose recovery deliberately.','error');break;
      case 'cloud-missing':setStatus('Sync stopped safely: this device remembers a prior cloud copy, but no current cloud state exists. Use Advanced / Recovery if you want to recreate it.','error');break;
      case 'incompatible':setStatus('Sync stopped safely: the cloud payload is not a compatible RosterBot state. Use Advanced / Recovery for deliberate replacement.','error');break;
    }}catch(err){if(String(err.message).includes('revision_conflict')){setStatus(`Sync stopped safely: ${err.message}. The cloud changed after RosterBot checked it, so nothing was overwritten.`, 'error');try{await fetchCloud();await updateUi()}catch(_){}}else setStatus(err.message,'error')}finally{setBusy(false)}}
